-- 443: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 1 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_443_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_443_guard;
INSERT INTO _migration_443_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_001' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation 2x + 3 = x + 9.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 6","B. x = 3","C. x = 4","D. x = 12"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Subtract x from both sides: x + 3 = 9. Then subtract 3 from both sides: x = 6. Check: 2(6) + 3 = 15 and 6 + 9 = 15, as required. Therefore the correct answer is A: x = 6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_001' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_443_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_002' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the equation (2x − 1)/3 + (x + 4)/2 = 4.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. x = 4","B. x = 2","C. x = 14","D. x = 3"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Multiply every term by 6, the LCM of 3 and 2: 2(2x − 1) + 3(x + 4) = 24, so 4x − 2 + 3x + 12 = 24. Hence 7x + 10 = 24, giving 7x = 14 and x = 2. Therefore the correct answer is B: x = 2.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_002' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_443_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_003' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Solve the simultaneous equations 2x + 3y = 12 and x + y = 5.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'x = 3 and y = 2' AND q.explanation IS 'From the second equation, x = 5 − y. Substituting into the first: 2(5 − y) + 3y = 12, so 10 − 2y + 3y = 12, giving y = 2. Then x = 5 − 2 = 3. Check: 2(3) + 3(2) = 6 + 6 = 12, as required. Answer: x = 3 and y = 2.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Solve' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_003' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_443_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_004' AND NOT (q.topic_id IS 'topic_wcoremath_algebra' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Make x the subject of the formula y = (3x − 2)/(x + 5).' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS 'x = (5y + 2)/(3 − y)' AND q.explanation IS 'Multiply both sides by (x + 5): y(x + 5) = 3x − 2, so xy + 5y = 3x − 2. Collect the terms in x: xy − 3x = −2 − 5y, so x(y − 3) = −(5y + 2). Dividing both sides by (y − 3) gives x = −(5y + 2)/(y − 3), which simplifies to x = (5y + 2)/(3 − y). Answer: x = (5y + 2)/(3 − y).' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Rearrange' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_004' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_443_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_005' AND NOT (q.topic_id IS 'topic_wcoremath_quadratic' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Find the product of the roots of the equation x² + 2x − 15 = 0.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 15","B. −2","C. −15","D. 2"]' AND q.correct_answer IS 'C' AND q.explanation IS 'For ax² + bx + c = 0 the product of the roots is c/a. Here c = −15 and a = 1, so the product is −15. (−2 is the sum of the roots, −b/a = −2 — a common confusion.) Therefore the correct answer is C: −15.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_005' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_001', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation 2x + 3 = x + 9.', 'multiple_choice', NULL, '["A. x = 6","B. x = 3","C. x = 4","D. x = 12"]', 'A', 'Subtract x from both sides: x + 3 = 9. Then subtract 3 from both sides: x = 6. Check: 2(6) + 3 = 15 and 6 + 9 = 15, as required. Therefore the correct answer is A: x = 6.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_002', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the equation (2x − 1)/3 + (x + 4)/2 = 4.', 'multiple_choice', NULL, '["A. x = 4","B. x = 2","C. x = 14","D. x = 3"]', 'B', 'Multiply every term by 6, the LCM of 3 and 2: 2(2x − 1) + 3(x + 4) = 24, so 4x − 2 + 3x + 12 = 24. Hence 7x + 10 = 24, giving 7x = 14 and x = 2. Therefore the correct answer is B: x = 2.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_003', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Solve the simultaneous equations 2x + 3y = 12 and x + y = 5.', 'calculation', NULL, NULL, 'x = 3 and y = 2', 'From the second equation, x = 5 − y. Substituting into the first: 2(5 − y) + 3y = 12, so 10 − 2y + 3y = 12, giving y = 2. Then x = 5 − 2 = 3. Check: 2(3) + 3(2) = 6 + 6 = 12, as required. Answer: x = 3 and y = 2.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Solve', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_004', 'topic_wcoremath_algebra', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Make x the subject of the formula y = (3x − 2)/(x + 5).', 'calculation', NULL, NULL, 'x = (5y + 2)/(3 − y)', 'Multiply both sides by (x + 5): y(x + 5) = 3x − 2, so xy + 5y = 3x − 2. Collect the terms in x: xy − 3x = −2 − 5y, so x(y − 3) = −(5y + 2). Dividing both sides by (y − 3) gives x = −(5y + 2)/(y − 3), which simplifies to x = (5y + 2)/(3 − y). Answer: x = (5y + 2)/(3 − y).', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Rearrange', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_005', 'topic_wcoremath_quadratic', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'Find the product of the roots of the equation x² + 2x − 15 = 0.', 'multiple_choice', NULL, '["A. 15","B. −2","C. −15","D. 2"]', 'C', 'For ax² + bx + c = 0 the product of the roots is c/a. Here c = −15 and a = 1, so the product is −15. (−2 is the sum of the roots, −b/a = −2 — a common confusion.) Therefore the correct answer is C: −15.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT id, 'wassce-core-math-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM questions WHERE id IN ('q_was_coremath_s2_001', 'q_was_coremath_s2_002', 'q_was_coremath_s2_003', 'q_was_coremath_s2_004', 'q_was_coremath_s2_005');
